function davidStarterMessages(): UIMessage[] {
  return [davidUiMessage("assistant", "Hi, I'm David. I can help you understand DataPlus workflows, troubleshoot a process, or prepare an operational next step. I won't make changes unless you use the relevant system controls.")]
}

function davidUiMessage(role: "user" | "assistant", text: string): UIMessage {
  return {
    id: globalThis.crypto?.randomUUID?.() || `david-${role}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
    role,
    parts: [{ type: "text", text }],
  }
}

function davidMessageText(message: UIMessage) {
  return message.parts.filter((part) => part.type === "text").map((part) => part.text).join("").trim()
}

type DavidActionProposal = {
  id?: string
  type?: string
  state?: "disabled" | "needs_input" | "already_linked" | "ready_for_approval" | string
  sku?: string
  productName?: string
  productType?: string
  available?: number
  price?: number
  missing?: string[]
  message?: string
  productUrl?: string
  expiresAt?: string
  skus?: string[]
  items?: Array<{ sku?: string; sellerSku?: string; title?: string; state?: string; message?: string }>
  eligibleItems?: Array<{ sku?: string; sellerSku?: string; title?: string; state?: string; message?: string }>
  itemCount?: number
  eligibleCount?: number
  source?: "chat" | "file" | string
}

function davidShopifyLaunchSku(message: string) {
  const normalized = message.trim()
  const match = normalized.match(/\b(?:launch|publish|push|create)\s+(?:sku\s*)?([A-Za-z0-9][A-Za-z0-9._-]{1,})\s+(?:on|to|in)\s+shopify\b/i)
    || normalized.match(/^\s*(?:launch|publish|push|create)\s+sku\s+([A-Za-z0-9][A-Za-z0-9._-]{1,})\s*$/i)
  return match?.[1]?.trim().toUpperCase() || ""
}

function davidWalmartRetirementSkus(message: string) {
  if (!/\bretir(?:e|ing|ement)\b/i.test(message) || !/\bwalmart\b/i.test(message)) return []
  const ignored = new Set(["RETIRE", "RETIRING", "RETIREMENT", "WALMART", "ITEM", "ITEMS", "SKU", "SKUS", "ON", "FROM", "THESE", "THIS", "PLEASE", "DAVID"])
  return [...new Set((message.match(/\b[A-Za-z0-9][A-Za-z0-9._-]{2,}\b/g) || [])
    .map((value) => value.toUpperCase())
    .filter((value) => /\d/.test(value) && !ignored.has(value)))]
}

function walmartRetirementFileSkus(text: string) {
  const rows = text.replace(/^\uFEFF/, "").split(/\r?\n/).filter((line) => line.trim())
  if (!rows.length) return []
  const delimiter = rows[0].includes("\t") ? "\t" : rows[0].includes(",") ? "," : ""
  const cells = (line: string) => {
    if (!delimiter) return [line.trim()]
    const values: string[] = []
    let value = "", quoted = false
    for (let index = 0; index < line.length; index++) {
      const character = line[index]
      if (character === '"' && quoted && line[index + 1] === '"') { value += '"'; index++; continue }
      if (character === '"') { quoted = !quoted; continue }
      if (character === delimiter && !quoted) { values.push(value.trim()); value = ""; continue }
      value += character
    }
    values.push(value.trim())
    return values
  }
  const first = cells(rows[0])
  const headerIndex = first.findIndex((value) => ["sku", "sellersku", "itemsku", "selleritemsku"].includes(value.toLowerCase().replace(/[^a-z]/g, "")))
  const start = headerIndex >= 0 ? 1 : 0
  const column = headerIndex >= 0 ? headerIndex : 0
  return [...new Set(rows.slice(start).map((line) => cells(line)[column]?.trim().toUpperCase() || "").filter((sku) => /^[A-Z0-9][A-Z0-9._-]{1,199}$/.test(sku)))]
}

function DavidMessageContent({ content }: { content: string }) {
  const inline = (value: string) => value.split(/(\*\*[^*]+\*\*)/g).filter(Boolean).map((part, index) => part.startsWith("**") && part.endsWith("**")
    ? <strong key={index}>{part.slice(2, -2)}</strong>
    : <span key={index}>{part}</span>)
  return <div className="grid gap-1.5">{content.split("\n").map((line, index) => {
    const numbered = line.match(/^\s*(\d+)\.\s+(.+)$/)
    const bullet = line.match(/^\s*[-*]\s+(.+)$/)
    if (numbered) return <div key={index} className="flex gap-2"><span className="shrink-0 text-muted-foreground">{numbered[1]}.</span><span>{inline(numbered[2])}</span></div>
    if (bullet) return <div key={index} className="flex gap-2"><span className="shrink-0 text-muted-foreground">-</span><span>{inline(bullet[1])}</span></div>
    return line ? <p key={index}>{inline(line)}</p> : <div key={index} className="h-1" />
  })}</div>
}

function appendDavidExchange(messages: UIMessage[], userText: string, assistantText: string) {
  return [...messages, davidUiMessage("user", userText), davidUiMessage("assistant", assistantText)]
}

function DavidConversation({
  settings,
  compact = false,
  onOpenSettings,
  onOpenFull,
}: {
  settings: SystemSettings
  compact?: boolean
  onOpenSettings: () => void
  onOpenFull?: () => void
}) {
  return <Suspense fallback={<div className={compact ? "flex min-h-0 flex-1 items-center justify-center" : "flex min-h-[560px] items-center justify-center"}><Loader2 className="size-5 animate-spin text-muted-foreground" /><span className="ml-2 text-sm text-muted-foreground">Opening David</span></div>}>
    <DavidAiClient id={compact ? "david-drawer" : "david-workspace"} initialMessages={davidStarterMessages()}>
      {(client) => <DavidConversationContent settings={settings} compact={compact} onOpenSettings={onOpenSettings} onOpenFull={onOpenFull} client={client} />}
    </DavidAiClient>
  </Suspense>
}

function DavidConversationContent({
  settings,
  compact = false,
  onOpenSettings,
  onOpenFull,
  client,
}: {
  settings: SystemSettings
  compact?: boolean
  onOpenSettings: () => void
  onOpenFull?: () => void
  client: DavidChatClient
}) {
  const [draft, setDraft] = useState("")
  const [actionBusy, setActionBusy] = useState(false)
  const [proposal, setProposal] = useState<DavidActionProposal | null>(null)
  const [retirementReason, setRetirementReason] = useState("")
  const [retirementConfirmation, setRetirementConfirmation] = useState("")
  const retirementFileInput = useRef<HTMLInputElement | null>(null)
  const scrollTarget = useRef<HTMLDivElement | null>(null)
  const { messages, sendMessage, setMessages, status, error, clearError } = client
  const provider = String(settings.aiProvider || "openai") === "google-ai-studio" ? "Google AI Studio" : "OpenAI"
  const ready = Boolean(settings.aiEnabled)
  const sending = status === "submitted" || status === "streaming" || actionBusy
  const actionScopes = settings.aiToolScopes as Record<string, unknown> | undefined
  const shopifyActionsEnabled = Boolean(settings.aiOperationalActionsEnabled && actionScopes?.["shopify.launch"])
  const walmartRetirementEnabled = Boolean(settings.aiOperationalActionsEnabled && actionScopes?.["walmart.retire"])

  useEffect(() => { scrollTarget.current?.scrollIntoView({ block: "end", behavior: "smooth" }) }, [messages, status])
  useEffect(() => {
    if (error) toast.error(error.message || "David is unavailable right now.")
  }, [error])

  async function prepareWalmartRetirement(skus: string[], userMessage: string, source: "chat" | "file") {
    setActionBusy(true)
    try {
      const result = await api<{ proposal?: DavidActionProposal }>("/api/ai/actions/walmart-retire/preflight", {
        method: "POST",
        body: JSON.stringify({ skus, source }),
      })
      const nextProposal = result.proposal || { type: "walmart_retire", state: "needs_input", skus, message: "David could not prepare that Walmart retirement review." }
      setProposal(nextProposal)
      setRetirementReason("")
      setRetirementConfirmation("")
      setMessages((current) => appendDavidExchange(current, userMessage, String(nextProposal.message || "Walmart retirement review completed.")))
    } catch (requestError) {
      const reply = requestError instanceof Error ? requestError.message : "David could not review that Walmart retirement request."
      setMessages((current) => appendDavidExchange(current, userMessage, reply))
      toast.error(reply)
    } finally {
      setActionBusy(false)
    }
  }

  async function chooseWalmartRetirementFile(file?: File | null) {
    if (!file || sending || !ready) return
    if (file.size > 5 * 1024 * 1024) { toast.error("Choose a CSV or text file smaller than 5 MB."); return }
    try {
      const skus = walmartRetirementFileSkus(await file.text())
      if (!skus.length) { toast.error("No valid SKUs were found. Use a SKU column or one SKU per line."); return }
      await prepareWalmartRetirement(skus, `Review ${skus.length.toLocaleString()} Walmart SKUs from ${file.name} for bulk retirement.`, "file")
    } catch (fileError) {
      toast.error(fileError instanceof Error ? fileError.message : "Unable to read the retirement file.")
    } finally {
      if (retirementFileInput.current) retirementFileInput.current.value = ""
    }
  }

  async function send() {
    const message = draft.trim()
    if (!message || sending || !ready) return
    setDraft("")
    clearError()
    const launchSku = davidShopifyLaunchSku(message)
    const retirementRequested = /\bretir(?:e|ing|ement)\b/i.test(message) && /\bwalmart\b/i.test(message)
    const pathSku = window.location.pathname.match(/^\/products\/([^/]+)$/)?.[1]
    const retirementSkus = davidWalmartRetirementSkus(message)
    if (retirementRequested && !retirementSkus.length && pathSku) retirementSkus.push(decodeURIComponent(pathSku).toUpperCase())
    if (retirementRequested) {
      await prepareWalmartRetirement(retirementSkus, message, "chat")
      return
    }
    if (launchSku) {
      setActionBusy(true)
      try {
        const result = await api<{ proposal?: DavidActionProposal }>("/api/ai/actions/shopify-launch/preflight", {
          method: "POST",
          body: JSON.stringify({ sku: launchSku }),
        })
        const nextProposal = result.proposal || { state: "needs_input", sku: launchSku, message: "David could not prepare that launch review." }
        setProposal(nextProposal)
        setMessages((current) => appendDavidExchange(current, message, String(nextProposal.message || "Shopify launch review completed.")))
      } catch (requestError) {
        const reply = requestError instanceof Error ? requestError.message : "David could not review that Shopify launch request."
        setMessages((current) => appendDavidExchange(current, message, reply))
        toast.error(reply)
      } finally {
        setActionBusy(false)
      }
      return
    }
    try {
      await sendMessage({ text: message })
    } catch (requestError) {
      toast.error(requestError instanceof Error ? requestError.message : "David is unavailable right now.")
    }
  }

  async function approveShopifyLaunch() {
    if (!proposal?.id || proposal.state !== "ready_for_approval" || actionBusy) return
    setActionBusy(true)
    try {
      const result = await api<{ message?: string; job?: ImportJob }>("/api/ai/actions/shopify-launch/execute", {
        method: "POST",
        body: JSON.stringify({ proposalId: proposal.id }),
      })
      const reply = result.message || `${proposal.sku || "SKU"} is queued for Shopify launch.`
      setMessages((current) => appendDavidExchange(current, `Approve Shopify launch for ${proposal.sku}.`, reply))
      setProposal(null)
      toast.success(result.job?.id ? `Shopify launch ${jobReference(result.job)} queued.` : reply)
    } catch (requestError) {
      const reply = requestError instanceof Error ? requestError.message : "Unable to queue the Shopify launch."
      setMessages((current) => appendDavidExchange(current, `Approve Shopify launch for ${proposal.sku}.`, reply))
      toast.error(reply)
    } finally {
      setActionBusy(false)
    }
  }

  async function approveWalmartRetirement() {
    if (!proposal?.id || proposal.type !== "walmart_retire" || proposal.state !== "ready_for_approval" || actionBusy) return
    setActionBusy(true)
    try {
      const result = await api<{ message?: string; job?: ImportJob }>("/api/ai/actions/walmart-retire/execute", {
        method: "POST",
        body: JSON.stringify({ proposalId: proposal.id, reason: retirementReason, confirmation: retirementConfirmation }),
      })
      const reply = result.message || "Walmart item retirement queued."
      setMessages((current) => appendDavidExchange(current, `Approve permanent Walmart retirement for ${proposal.eligibleCount ?? proposal.eligibleItems?.length ?? 0} item(s).`, reply))
      setProposal(null)
      setRetirementReason("")
      setRetirementConfirmation("")
      toast.success(result.job?.id ? `Walmart retirement ${jobReference(result.job)} queued.` : reply)
    } catch (requestError) {
      const reply = requestError instanceof Error ? requestError.message : "Unable to queue Walmart retirement."
      setMessages((current) => appendDavidExchange(current, "Approve Walmart retirement.", reply))
      toast.error(reply)
    } finally {
      setActionBusy(false)
    }
  }

  return <div className={compact ? "flex min-h-0 flex-1 flex-col" : "flex min-h-[560px] flex-col"}>
    <div className="flex items-start justify-between gap-3 border-b px-4 py-3 pr-12">
      <div>
        <div className="flex items-center gap-2"><MessageSquare className="size-4 text-primary" /><h2 className="font-semibold">David</h2><Badge variant={ready ? "secondary" : "outline"}>{ready ? provider : "Setup required"}</Badge></div>
        <p className="mt-1 text-xs text-muted-foreground">{String(settings.aiModel || "Default model")} - guided actions require your approval</p>
      </div>
      <div className="flex shrink-0 items-center gap-1">
        {onOpenFull ? <Button variant="ghost" size="icon" title="Open full workspace" onClick={onOpenFull}><PanelRightOpen className="size-4" /></Button> : null}
        <Button variant="ghost" size="sm" onClick={() => { setMessages(davidStarterMessages()); setProposal(null); setRetirementReason(""); setRetirementConfirmation("") }}>New chat</Button>
      </div>
    </div>
    {!ready ? <Alert className="m-4"><AlertCircle className="size-4" /><AlertTitle>David is not enabled</AlertTitle><AlertDescription className="flex flex-wrap items-center justify-between gap-2">Verify the AI integration before starting a chat.<Button size="sm" variant="outline" onClick={onOpenSettings}>AI settings</Button></AlertDescription></Alert> : null}
    <div className={compact ? "min-h-0 flex-1 overflow-y-auto p-4" : "flex-1 overflow-y-auto p-4"}>
      <div className="grid content-start gap-3">
        {messages.map((message) => {
          const content = davidMessageText(message)
          if (!content) return null
          return <div key={message.id} className={message.role === "user" ? "ml-auto max-w-[85%] rounded-lg bg-primary px-3 py-2 text-sm text-primary-foreground" : "ai-result-surface mr-auto max-w-[88%] whitespace-pre-wrap rounded-lg border px-3 py-2 text-sm shadow-sm"}>
            <p className="mb-1 text-xs font-semibold opacity-70">{message.role === "user" ? "You" : "David"}</p><DavidMessageContent content={content} />
          </div>
        })}
        {proposal?.type === "walmart_retire" ? <Card className="ai-result-surface mr-auto w-full max-w-[92%] shadow-none">
          <CardContent className="grid gap-3 p-3">
            <div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-sm font-semibold">Walmart retirement review</p><p className="text-xs text-muted-foreground">{proposal.source === "file" ? "Uploaded bulk retirement" : "Permanent marketplace action"}</p></div><Badge variant={proposal.state === "ready_for_approval" ? "destructive" : "outline"}>{proposal.state === "ready_for_approval" ? `${proposal.eligibleCount ?? proposal.eligibleItems?.length ?? 0} ready` : proposal.state === "disabled" ? "Actions disabled" : "Needs review"}</Badge></div>
            <div className="max-h-48 overflow-y-auto rounded-md border bg-background"><div className="divide-y">{proposal.items?.map((item) => <div key={String(item.sku)} className="grid grid-cols-[minmax(0,1fr)_auto] gap-2 px-3 py-2 text-xs"><div className="min-w-0"><p className="truncate font-medium">{item.sku}</p>{item.sellerSku && item.sellerSku !== item.sku ? <p className="truncate text-muted-foreground">Seller SKU: {item.sellerSku}</p> : null}</div><Badge variant={item.state === "ready" ? "secondary" : item.state === "already_retired" ? "outline" : "destructive"}>{item.message || item.state}</Badge></div>)}</div></div>
            {(proposal.itemCount || 0) > (proposal.items?.length || 0) ? <p className="text-xs text-muted-foreground">Showing the first {proposal.items?.length || 0} of {numberLabel(proposal.itemCount || 0)} reviewed SKUs. The job artifact will contain every result.</p> : null}
            {proposal.state === "ready_for_approval" ? <div className="grid gap-3 rounded-md border border-destructive/30 bg-destructive/5 p-3"><Field label="Retirement reason"><Input value={retirementReason} onChange={(event) => setRetirementReason(event.target.value)} maxLength={500} placeholder="For example: discontinued by supplier" /></Field><Field label={`Enter RETIRE ${proposal.eligibleCount ?? proposal.eligibleItems?.length ?? 0} to confirm`}><Input value={retirementConfirmation} onChange={(event) => setRetirementConfirmation(event.target.value)} autoComplete="off" /></Field><p className="text-xs text-muted-foreground">This permanently retires only the ready, linked seller SKUs. Excluded items are not changed.</p></div> : null}
            <div className="flex flex-wrap justify-end gap-2">{proposal.state === "ready_for_approval" ? <Button variant="destructive" size="sm" disabled={!walmartRetirementEnabled || actionBusy || retirementReason.trim().length < 5 || retirementConfirmation.trim().toUpperCase() !== `RETIRE ${proposal.eligibleCount ?? proposal.eligibleItems?.length ?? 0}`} onClick={() => void approveWalmartRetirement()}>{actionBusy ? <Loader2 className="size-4 animate-spin" /> : <Ban className="size-4" />} Schedule bulk retirement</Button> : null}</div>
            {proposal.state === "ready_for_approval" && !walmartRetirementEnabled ? <p className="text-xs text-muted-foreground">Enable David operational actions and Walmart item retirement in System Settings before approval.</p> : null}
          </CardContent>
        </Card> : proposal ? <Card className="ai-result-surface mr-auto max-w-[88%] shadow-none">
          <CardContent className="grid gap-3 p-3">
            <div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-sm font-semibold">Shopify launch review</p><p className="text-xs text-muted-foreground">{proposal.sku || "SKU"}{proposal.productName ? ` - ${proposal.productName}` : ""}</p></div><Badge variant={proposal.state === "ready_for_approval" ? "default" : proposal.state === "already_linked" ? "secondary" : "outline"}>{proposal.state === "ready_for_approval" ? "Ready for approval" : proposal.state === "already_linked" ? "Already linked" : proposal.state === "disabled" ? "Actions disabled" : "Needs information"}</Badge></div>
            {proposal.state === "ready_for_approval" ? <div className="grid gap-1 rounded-md border bg-background p-2 text-xs text-muted-foreground"><span>Product type: {proposal.productType || "Not set"}</span><span>Available: {Number(proposal.available || 0).toLocaleString()}</span><span>Price: {moneyLabel(proposal.price || 0)}</span>{proposal.expiresAt ? <span>Approval expires {dateLabel(proposal.expiresAt)}</span> : null}</div> : null}
            {proposal.missing?.length ? <div className="rounded-md border border-amber-300 bg-amber-50 p-2 text-xs text-amber-950"><p className="font-medium">Complete before launch</p><p className="mt-1">{proposal.missing.join(", ")}</p></div> : null}
            <div className="flex flex-wrap justify-end gap-2">{proposal.productUrl ? <Button asChild variant="outline" size="sm"><a href={proposal.productUrl}>Open product</a></Button> : null}{proposal.state === "ready_for_approval" ? <Button size="sm" disabled={!shopifyActionsEnabled || actionBusy} onClick={() => void approveShopifyLaunch()}>{actionBusy ? <Loader2 className="size-4 animate-spin" /> : <Play className="size-4" />} Queue Shopify launch</Button> : null}</div>
            {proposal.state === "ready_for_approval" && !shopifyActionsEnabled ? <p className="text-xs text-muted-foreground">Enable David operational actions and Shopify SKU launch in System Settings before approval.</p> : null}
          </CardContent>
        </Card> : null}
        {sending ? <div className="mr-auto flex items-center gap-2 rounded-lg border bg-background px-3 py-2 text-sm text-muted-foreground"><Loader2 className="size-4 animate-spin" /> David is thinking</div> : null}
        <div ref={scrollTarget} />
      </div>
    </div>
    <div className="border-t bg-background p-3">
      <div className="flex items-end gap-2 rounded-lg border bg-muted/20 p-2">
        <input ref={retirementFileInput} type="file" accept=".csv,.txt,text/csv,text/plain" className="sr-only" onChange={(event) => void chooseWalmartRetirementFile(event.target.files?.[0])} />
        <Button type="button" size="icon" variant="ghost" className="shrink-0" disabled={!ready || sending} onClick={() => retirementFileInput.current?.click()} title="Upload Walmart retirement SKUs"><FileUp className="size-4" /></Button>
        <Textarea className="min-h-11 resize-none border-0 bg-transparent shadow-none focus-visible:ring-0" disabled={!ready || sending} value={draft} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); void send() } }} rows={compact ? 2 : 3} placeholder={ready ? "Ask David anything..." : "Enable AI integration to chat with David"} />
        <Button size="icon" className="shrink-0" disabled={!ready || sending || !draft.trim()} onClick={() => void send()} title="Send message"><SendHorizontal className="size-4" /></Button>
      </div>
    </div>
  </div>
}

function DavidChatDrawer({ open, onOpenChange, settings, onOpenSettings, onOpenFull }: { open: boolean; onOpenChange: (open: boolean) => void; settings: SystemSettings; onOpenSettings: () => void; onOpenFull: () => void }) {
  const [mobile, setMobile] = useState(() => window.matchMedia("(max-width: 639px)").matches)
  useEffect(() => {
    const media = window.matchMedia("(max-width: 639px)")
    const sync = () => setMobile(media.matches)
    sync(); media.addEventListener("change", sync)
    return () => media.removeEventListener("change", sync)
  }, [])
  if (mobile) return <Drawer open={open} onOpenChange={onOpenChange} repositionInputs={false}>
    <DrawerContent className="h-[88dvh]">
      <DrawerHeader className="sr-only"><DrawerTitle>David</DrawerTitle><DrawerDescription>DataPlus operational assistant</DrawerDescription></DrawerHeader>
      <div className="min-h-0 flex-1"><DavidConversation compact settings={settings} onOpenSettings={onOpenSettings} onOpenFull={onOpenFull} /></div>
    </DrawerContent>
  </Drawer>
  return <Sheet open={open} onOpenChange={onOpenChange}>
    <SheetContent side="right" className="w-full gap-0 p-0 sm:max-w-[440px]">
      <DavidConversation compact settings={settings} onOpenSettings={onOpenSettings} onOpenFull={onOpenFull} />
    </SheetContent>
  </Sheet>
}

function DavidChatPage({ settings, onOpenSettings }: { settings: SystemSettings; onOpenSettings: () => void }) {
  const provider = String(settings.aiProvider || "openai") === "google-ai-studio" ? "Google AI Studio" : "OpenAI"
  const ready = Boolean(settings.aiEnabled)
  return <div className="mx-auto grid w-full max-w-5xl gap-5">
    <PageHeader
      eyebrow="AI assistant"
      title="David"
      description="An operational assistant that uses enabled, page-aware scopes and prepares approved actions. Chat history stays in this browser session."
      action={<div className="flex items-center gap-2"><Badge variant={ready ? "default" : "secondary"}>{ready ? `${provider} connected` : "AI setup required"}</Badge><Button variant="outline" size="sm" onClick={onOpenSettings}><Settings className="size-4" /> AI settings</Button></div>}
    />
    <Card className="overflow-hidden"><DavidConversation settings={settings} onOpenSettings={onOpenSettings} /></Card>
  </div>
}

const releaseTypeLabels: Record<string, string> = {
  data: "Data",
  deployment: "Deployment",
  documentation: "Documentation",
  feature: "Feature",
  fix: "Fix",
  interface: "Interface",
  maintenance: "Maintenance",
  performance: "Performance",
  security: "Security",
}

function releaseBadgeClass(type: string) {
  if (type === "feature") return "border-emerald-500/30 bg-emerald-500/10 text-emerald-700 dark:text-emerald-300"
  if (type === "fix") return "border-red-500/30 bg-red-500/10 text-red-700 dark:text-red-300"
  if (type === "interface") return "border-blue-500/30 bg-blue-500/10 text-blue-700 dark:text-blue-300"
  if (type === "performance") return "border-violet-500/30 bg-violet-500/10 text-violet-700 dark:text-violet-300"
  if (type === "data") return "border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-300"
  if (type === "deployment") return "border-cyan-500/30 bg-cyan-500/10 text-cyan-700 dark:text-cyan-300"
  if (type === "security") return "border-orange-500/30 bg-orange-500/10 text-orange-700 dark:text-orange-300"
  return "border-border bg-muted text-muted-foreground"
}

export function ReleaseHistorySettings({ active }: { active: boolean }) {
  const [history, setHistory] = useState<ReleaseHistoryResponse | null>(null)
  const [releases, setReleases] = useState<ReleaseChange[]>([])
  const [query, setQuery] = useState("")
  const [type, setType] = useState("all")
  const [view, setView] = useState<"releases" | "changes">("releases")
  const [loading, setLoading] = useState(false)
  const [loadingMore, setLoadingMore] = useState(false)
  const [error, setError] = useState("")
  const [lastSeen, setLastSeen] = useState(() => window.localStorage.getItem("dataplus:last-seen-release") || "")

  async function load(reset = true) {
    const offset = reset ? 0 : releases.length
    if (reset) setLoading(true)
    else setLoadingMore(true)
    setError("")
    try {
      const params = new URLSearchParams({ limit: "30", offset: String(offset), type })
      if (query.trim()) params.set("q", query.trim())
      const result = await api<ReleaseHistoryResponse>(`/api/system/releases?${params.toString()}`)
      setHistory(result)
      setReleases((current) => reset ? result.releases : [...current, ...result.releases])
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : "Unable to load release history.")
    } finally {
      setLoading(false)
      setLoadingMore(false)
    }
  }

  useEffect(() => {
    if (!active) return
    const timer = window.setTimeout(() => void load(true), 250)
    return () => window.clearTimeout(timer)
  }, [active, query, type])

  const viewingFilteredHistory = Boolean(query.trim() || type !== "all")
  const lastSeenIndex = lastSeen ? releases.findIndex((release) => release.id === lastSeen) : -1
  const newCount = viewingFilteredHistory || !lastSeen
    ? 0
    : lastSeenIndex >= 0
      ? lastSeenIndex
      : Math.min(releases.length, history?.total || releases.length)
  const hasMore = Boolean(history && releases.length < history.filteredTotal)
  const deploymentStatus = String(history?.deployment?.status || "unknown").toLowerCase()
  const deploymentHealthy = deploymentStatus === "healthy" && history?.deployment?.revisionMatchesHistory !== false

  function markViewed() {
    const revision = history?.current?.id
    if (!revision) return
    window.localStorage.setItem("dataplus:last-seen-release", revision)
    setLastSeen(revision)
    toast.success("Release history marked as viewed.")
  }

  return <div className="grid gap-4">
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
      <MetricCard label="Current release" value={history?.currentGroup?.version || history?.current?.shortId || "Loading"} icon={History} />
      <MetricCard label="Changes recorded" value={numberLabel(history?.total || 0)} icon={FileText} />
      <MetricCard label="Production" value={history?.deployment ? (deploymentHealthy ? "Healthy" : deploymentStatus) : "Not reported"} icon={deploymentHealthy ? CheckCircle2 : AlertTriangle} />
      <MetricCard label="Deployed" value={history?.deployment?.deployedAt ? dateLabel(history.deployment.deployedAt) : "Not reported"} icon={RefreshCw} />
    </div>

    {history?.deployment && <Alert className={deploymentHealthy ? "border-emerald-500/30 bg-emerald-500/5" : "border-amber-500/40 bg-amber-500/5"}>
      {deploymentHealthy ? <CheckCircle2 className="size-4 text-emerald-600" /> : <AlertTriangle className="size-4 text-amber-600" />}
      <AlertTitle>{deploymentHealthy ? "Production deployment is healthy" : `Production deployment is ${deploymentStatus}`}</AlertTitle>
      <AlertDescription className="flex flex-wrap gap-x-4 gap-y-1">
        <span>Revision #{history.deployment.shortRevision || history.deployment.revision?.slice(0, 7) || "unknown"}</span>
        <span>Environment: {history.deployment.environment || "production"}</span>
        {history.deployment.durationSeconds !== null && history.deployment.durationSeconds !== undefined && <span>Duration: {numberLabel(history.deployment.durationSeconds)} seconds</span>}
        {history.deployment.revisionMatchesHistory === false && <span className="font-medium text-amber-700 dark:text-amber-300">A newer repository revision is waiting to deploy.</span>}
        {history.deployment.serviceUrl && <a className="font-medium text-primary hover:underline" href={history.deployment.serviceUrl} target="_blank" rel="noreferrer">Open production</a>}
      </AlertDescription>
    </Alert>}

    <Card>
      <CardHeader className="gap-4 border-b lg:flex-row lg:items-center lg:justify-between">
        <div>
          <CardTitle className="text-base">Releases and changes</CardTitle>
          <CardDescription>Deployment-aware history generated from Git. New commits are added automatically during every production deployment.</CardDescription>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button variant="outline" size="sm" onClick={() => void load(true)} disabled={loading}><RefreshCw className={cn("size-4", loading && "animate-spin")} /> Refresh</Button>
          <Button variant="outline" size="sm" onClick={markViewed} disabled={!history?.current || newCount === 0}>Mark viewed</Button>
        </div>
      </CardHeader>
      <CardContent className="grid gap-4 p-4">
        <Tabs value={view} onValueChange={(value) => setView(value as "releases" | "changes")}>
          <TabsList><TabsTrigger value="releases">Named releases</TabsTrigger><TabsTrigger value="changes">All changes</TabsTrigger></TabsList>
        </Tabs>
        <div className="grid gap-3 md:grid-cols-[minmax(0,1fr)_220px]">
          <div className="relative"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground" /><Input className="pl-9" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search releases, files, areas, or commit ID" /></div>
          <Select value={type} onValueChange={setType}><SelectTrigger><SelectValue placeholder="All change types" /></SelectTrigger><SelectContent><SelectItem value="all">All change types</SelectItem>{Object.entries(releaseTypeLabels).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select>
        </div>

        {error && <Alert variant="destructive"><AlertCircle className="size-4" /><AlertTitle>Release history unavailable</AlertTitle><AlertDescription>{error}</AlertDescription></Alert>}
        {loading && <div className="grid gap-2">{Array.from({ length: 5 }).map((_, index) => <Skeleton key={index} className="h-20 w-full" />)}</div>}
        {!loading && !error && view === "releases" && <div className="grid gap-3">
          {(history?.releaseGroups || []).map((group) => <Collapsible key={group.id} className="overflow-hidden rounded-lg border bg-card">
            <div className="flex flex-col gap-3 p-4 lg:flex-row lg:items-start lg:justify-between">
              <div className="min-w-0 space-y-2">
                <div className="flex flex-wrap items-center gap-2"><Badge variant={group.current ? "default" : "secondary"}>{group.current ? "Current" : "Release"}</Badge><Badge variant="outline" className={releaseBadgeClass(group.primaryType)}>{releaseTypeLabels[group.primaryType] || "Maintenance"}</Badge><span className="font-mono text-xs font-semibold text-foreground">v{group.version}</span></div>
                <div><p className="font-semibold text-foreground">{group.name}</p><p className="mt-1 text-sm text-muted-foreground">{numberLabel(group.changeCount)} changes across {(group.areas || []).join(", ") || "the application"}.</p></div>
                <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground"><span>Revision #{group.shortRevision || "unknown"}</span><span>{numberLabel(group.fileCount)} files changed</span><span>{dateLabel(group.publishedAt)}</span></div>
              </div>
              <CollapsibleTrigger asChild><Button variant="outline" size="sm">View release notes</Button></CollapsibleTrigger>
            </div>
            <CollapsibleContent className="border-t bg-muted/20">
              <div className="divide-y">{group.changes.map((release) => <div key={release.id} className="grid gap-2 p-4 sm:grid-cols-[auto_minmax(0,1fr)_auto] sm:items-start"><Badge variant="outline" className={releaseBadgeClass(release.type)}>{releaseTypeLabels[release.type] || release.type}</Badge><div className="min-w-0"><p className="text-sm font-medium text-foreground">{release.title}</p><p className="mt-1 text-xs text-muted-foreground">{release.author || "Unknown author"} / {(release.areas || []).join(" / ") || "Repository"}</p></div>{release.commitUrl && <Button variant="ghost" size="icon" asChild title="View commit"><a href={release.commitUrl} target="_blank" rel="noreferrer"><ExternalLink className="size-4" /></a></Button>}</div>)}</div>
            </CollapsibleContent>
          </Collapsible>)}
          {!(history?.releaseGroups || []).length && <Empty className="rounded-lg border py-12"><EmptyHeader><EmptyMedia variant="icon"><History /></EmptyMedia><EmptyTitle>No matching releases</EmptyTitle><EmptyDescription>Adjust the search or change-type filter.</EmptyDescription></EmptyHeader></Empty>}
        </div>}
        {!loading && !error && view === "changes" && <div className="overflow-hidden rounded-lg border">
          {releases.map((release, index) => {
            const isNew = Boolean(!viewingFilteredHistory && lastSeen && (lastSeenIndex === -1 || index < lastSeenIndex))
            return <Collapsible key={release.id} className="border-b last:border-b-0">
              <div className="flex flex-col gap-3 p-4 lg:flex-row lg:items-start lg:justify-between">
                <div className="min-w-0 space-y-2">
                  <div className="flex flex-wrap items-center gap-2"><Badge variant="outline" className={releaseBadgeClass(release.type)}>{releaseTypeLabels[release.type] || release.type || "Change"}</Badge>{isNew && <Badge variant="info">New</Badge>}<span className="font-mono text-xs text-muted-foreground">#{release.shortId}</span>{(release.tags || []).map((tag) => <Badge key={tag} variant="secondary">{tag}</Badge>)}</div>
                  <p className="font-medium text-foreground">{release.title}</p>
                  <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground"><span>{release.author || "Unknown author"}</span><span>{dateLabel(release.committedAt)}</span><span>{numberLabel(release.fileCount || release.files?.length || 0)} files</span><span>{(release.areas || []).join(" / ") || "Repository"}</span></div>
                </div>
                <div className="flex shrink-0 gap-2"><CollapsibleTrigger asChild><Button variant="outline" size="sm">Details</Button></CollapsibleTrigger>{release.commitUrl && <Button variant="outline" size="icon" asChild title="View commit"><a href={release.commitUrl} target="_blank" rel="noreferrer"><ExternalLink className="size-4" /></a></Button>}</div>
              </div>
              <CollapsibleContent className="border-t bg-muted/20 px-4 py-3">
                {release.notes && <p className="mb-3 whitespace-pre-wrap text-sm text-muted-foreground">{release.notes}</p>}
                <p className="mb-2 text-xs font-semibold uppercase text-muted-foreground">Changed files</p>
                <div className="grid gap-1 font-mono text-xs text-muted-foreground sm:grid-cols-2">{(release.files || []).map((file) => <span key={file} className="truncate" title={file}>{file}</span>)}{!(release.files || []).length && <span>No file list recorded.</span>}</div>
              </CollapsibleContent>
            </Collapsible>
          })}
          {!releases.length && <Empty className="py-12"><EmptyHeader><EmptyMedia variant="icon"><History /></EmptyMedia><EmptyTitle>No matching releases</EmptyTitle><EmptyDescription>Adjust the search or change-type filter.</EmptyDescription></EmptyHeader></Empty>}
        </div>}

        {view === "changes" && hasMore && <Button variant="outline" onClick={() => void load(false)} disabled={loadingMore}>{loadingMore && <Loader2 className="size-4 animate-spin" />} Load more changes</Button>}
        {history && <p className="text-xs text-muted-foreground">{view === "releases" ? `Showing ${numberLabel(history.releaseGroups?.length || 0)} of ${numberLabel(history.releaseGroupTotal || history.releaseGroups?.length || 0)} named releases` : `Showing ${numberLabel(releases.length)} of ${numberLabel(history.filteredTotal)} matching changes`}. Source: {history.source === "git" ? "live repository history" : "deployment manifest"}. {numberLabel(newCount)} new since last viewed.</p>}
      </CardContent>
    </Card>
  </div>
}

export type SupplierIndexStatus = {
  enabled?: boolean
  totalProducts?: number
  totalLinks?: number
  linkedProducts?: number
  multiSupplierProducts?: number
  unmatchedProducts?: number
  pendingReviews?: number
  lastRebuiltAt?: string
  methodCounts?: Array<{ matchType?: string; productCount?: number; linkCount?: number }>
  activeJobId?: string
  activeJob?: ImportJob | null
}

type WikiHealthResult = {
  ready?: boolean
  checkedAt?: string
  message?: string
  apiConfigured?: boolean
  systemSettings?: SystemSettings
}

function WikiWorkspace({
  settings,
  onSaveSettings,
}: {
  settings: SystemSettings
  onSaveSettings: (patch: Record<string, unknown>) => Promise<void>
}) {
  const [draft, setDraft] = useState(() => ({
    wikiEnabled: settings.wikiEnabled !== false,
    wikiAutomationEnabled: settings.wikiAutomationEnabled === true,
    wikiRequireReview: settings.wikiRequireReview !== false,
    wikiHandbookShelf: String(settings.wikiHandbookShelf || "DataPlus Operations Handbook"),
    wikiDefaultOwner: String(settings.wikiDefaultOwner || "DataPlus Operations"),
  }))
  const [saving, setSaving] = useState(false)
  const [checking, setChecking] = useState(false)
  const [health, setHealth] = useState<WikiHealthResult | null>(null)
  const wikiUrl = String(settings.wikiBaseUrl || "https://dataplusapp.duckdns.org/wiki").replace(/\/+$/, "")
  const effectiveHealthStatus = health?.ready === true ? "ready" : health?.ready === false ? "failed" : String(settings.wikiLastHealthStatus || "not_checked")
  const healthMessage = health?.message || String(settings.wikiLastHealthMessage || "No connection check has been run yet.")
  const healthAt = health?.checkedAt || String(settings.wikiLastHealthCheckAt || "")

  useEffect(() => {
    setDraft({
      wikiEnabled: settings.wikiEnabled !== false,
      wikiAutomationEnabled: settings.wikiAutomationEnabled === true,
      wikiRequireReview: settings.wikiRequireReview !== false,
      wikiHandbookShelf: String(settings.wikiHandbookShelf || "DataPlus Operations Handbook"),
      wikiDefaultOwner: String(settings.wikiDefaultOwner || "DataPlus Operations"),
    })
  }, [settings.wikiEnabled, settings.wikiAutomationEnabled, settings.wikiRequireReview, settings.wikiHandbookShelf, settings.wikiDefaultOwner])

  async function save() {
    setSaving(true)
    try {
      await onSaveSettings({
        wikiEnabled: draft.wikiEnabled,
        wikiAutomationEnabled: draft.wikiAutomationEnabled,
        wikiRequireReview: draft.wikiRequireReview,
        wikiHandbookShelf: draft.wikiHandbookShelf.trim() || "DataPlus Operations Handbook",
        wikiDefaultOwner: draft.wikiDefaultOwner.trim() || "DataPlus Operations",
      })
    } finally {
      setSaving(false)
    }
  }

  async function checkHealth() {
    setChecking(true)
    try {
      const result = await api<WikiHealthResult>("/api/wiki/health", { method: "POST", body: JSON.stringify({}) })
      setHealth(result)
      toast.success(result.message || "Wiki connection verified.")
    } catch (error) {
      setHealth({ ready: false, message: error instanceof Error ? error.message : "Unable to reach the wiki." })
      toast.error(error instanceof Error ? error.message : "Unable to reach the wiki.")
    } finally {
      setChecking(false)
    }
  }

  return (
    <div className="grid gap-5">
      <PageHeader
        eyebrow="Workspace / Wiki"
        title="Operations Wiki"
        description="Control how DataPlus connects to the shared operating handbook. BookStack holds the documents and its own user permissions; DataPlus controls the operating policy."
        action={<div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => void checkHealth()} disabled={checking}>{checking ? <Loader2 className="size-4 animate-spin" /> : <RefreshCw className="size-4" />} Test connection</Button><Button asChild><a href={`${wikiUrl}/`} target="_blank" rel="noreferrer"><ExternalLink className="size-4" /> Open wiki</a></Button></div>}
      />

      <div className="grid gap-4 xl:grid-cols-[1.1fr_0.9fr]">
        <Card>
          <CardHeader>
            <CardTitle>Connection</CardTitle>
            <CardDescription>The documentation service is hosted alongside DataPlus but has its own login and permissions.</CardDescription>
          </CardHeader>
          <CardContent className="grid gap-4">
            <div className="grid gap-3 sm:grid-cols-2">
              <Detail label="Service" value="BookStack" />
              <Detail label="API credential" value={(health?.apiConfigured ?? Boolean(settings.wikiApiConfigured)) ? "Configured on server" : "Not configured"} />
              <Detail label="Last check" value={healthAt ? dateLabel(healthAt) : "Not checked"} />
              <Detail label="Status" value={effectiveHealthStatus === "ready" ? "Ready" : effectiveHealthStatus === "failed" ? "Needs attention" : "Not checked"} />
            </div>
            <div className={cn("rounded-md border p-3 text-sm", effectiveHealthStatus === "ready" ? "border-emerald-500/30 bg-emerald-500/5" : effectiveHealthStatus === "failed" ? "border-destructive/30 bg-destructive/5" : "bg-muted/30")}>
              <div className="flex flex-wrap items-center gap-2"><Badge variant={effectiveHealthStatus === "ready" ? "default" : effectiveHealthStatus === "failed" ? "destructive" : "secondary"}>{effectiveHealthStatus === "ready" ? "Connected" : effectiveHealthStatus === "failed" ? "Connection issue" : "Not checked"}</Badge><span className="text-muted-foreground">{healthMessage}</span></div>
            </div>
            <Field label="Wiki address"><Input value={wikiUrl} disabled readOnly /><p className="text-xs text-muted-foreground">The application address is fixed to the protected DataPlus wiki path.</p></Field>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Publishing safeguards</CardTitle>
            <CardDescription>Keep operational knowledge organized without letting background automation publish unchecked changes.</CardDescription>
          </CardHeader>
          <CardContent className="grid gap-3">
            <ToggleField label="Enable wiki workspace" description="Makes the Operations Wiki available from the DataPlus workspace navigation." checked={draft.wikiEnabled} onCheckedChange={(value) => setDraft((current) => ({ ...current, wikiEnabled: value }))} />
            <ToggleField label="Enable automated publishing" description="Allows approved future DataPlus automations to create or update handbook drafts through the BookStack API." checked={draft.wikiAutomationEnabled} onCheckedChange={(value) => setDraft((current) => ({ ...current, wikiAutomationEnabled: value }))} />
            <ToggleField label="Require review before publishing" description="Keeps generated or revised handbook content in review until an owner approves it." checked={draft.wikiRequireReview} onCheckedChange={(value) => setDraft((current) => ({ ...current, wikiRequireReview: value }))} />
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Handbook organization</CardTitle>
          <CardDescription>These names tell future automation where to place operational documentation. They do not alter existing BookStack pages.</CardDescription>
        </CardHeader>
        <CardContent className="grid gap-4 md:grid-cols-2">
          <Field label="Handbook shelf"><Input value={draft.wikiHandbookShelf} onChange={(event) => setDraft((current) => ({ ...current, wikiHandbookShelf: event.target.value }))} placeholder="DataPlus Operations Handbook" /></Field>
          <Field label="Default owner"><Input value={draft.wikiDefaultOwner} onChange={(event) => setDraft((current) => ({ ...current, wikiDefaultOwner: event.target.value }))} placeholder="DataPlus Operations" /></Field>
          <div className="md:col-span-2 flex flex-wrap items-center justify-between gap-3 rounded-md border bg-muted/25 p-3">
            <p className="text-sm text-muted-foreground">BookStack administrators manage users and API tokens in BookStack. DataPlus only reports whether a server-managed automation credential exists; secrets are never sent back to the browser.</p>
            <Button onClick={() => void save()} disabled={saving}>{saving && <Loader2 className="size-4 animate-spin" />} Save controls</Button>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

function DetailBreadcrumb({ items }: { items: Array<{ label: string; href?: string }> }) {
  return <Breadcrumb><BreadcrumbList>{items.map((item, index) => <div key={`${item.label}-${index}`} className="contents"><BreadcrumbItem>{item.href ? <BreadcrumbLink asChild><a href={item.href}>{item.label}</a></BreadcrumbLink> : <BreadcrumbPage>{item.label}</BreadcrumbPage>}</BreadcrumbItem>{index < items.length - 1 && <BreadcrumbSeparator />}</div>)}</BreadcrumbList></Breadcrumb>
}

type ContextAction = {
  id: string
  label: string
  description?: string
  icon?: React.ReactNode
  onSelect: () => void
  disabled?: boolean
  group?: "Primary" | "Utilities" | "Danger zone"
  destructive?: boolean
}

export function ContextActions({
  actions,
  label = "Actions",
  disabled = false,
}: {
  actions: ContextAction[]
  label?: string
  disabled?: boolean
}) {
  const [open, setOpen] = useState(false)
  const groups: Array<ContextAction["group"]> = ["Primary", "Utilities", "Danger zone"]
  const grouped = groups.map((group) => ({ group, actions: actions.filter((action) => (action.group || "Primary") === group) })).filter((entry) => entry.actions.length)

  return <>
    <Button size="sm" disabled={disabled} onClick={() => setOpen(true)} className="border border-blue-700 bg-blue-600 font-semibold text-white shadow-sm hover:bg-blue-700 dark:border-blue-400 dark:bg-blue-500 dark:hover:bg-blue-400">
      <MoreHorizontal className="size-4" /> {label}
    </Button>
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="w-[calc(100%-2rem)] max-w-[34rem] gap-0 overflow-hidden p-0">
        <DialogHeader className="border-b px-4 py-3">
          <DialogTitle>{label}</DialogTitle>
          <DialogDescription>Search or choose an action for this workspace.</DialogDescription>
        </DialogHeader>
        <Command>
          <CommandInput placeholder="Find an action..." />
          <CommandList className="max-h-[min(60vh,28rem)]">
            <CommandEmpty>No actions match your search.</CommandEmpty>
            {grouped.map((entry, index) => <div key={entry.group}>
              {index > 0 && <CommandSeparator />}
              <CommandGroup heading={entry.group}>
                {entry.actions.map((action) => <CommandItem
                  key={action.id}
                  value={`${action.label} ${action.description || ""}`}
                  disabled={action.disabled}
                  onSelect={() => {
                    if (action.disabled) return
                    setOpen(false)
                    action.onSelect()
                  }}
                  className={action.destructive ? "text-destructive data-[selected=true]:bg-destructive/10 data-[selected=true]:text-destructive" : ""}
                >
                  <span className={cn("flex size-8 shrink-0 items-center justify-center rounded-md border bg-muted/50", action.destructive && "border-destructive/30 bg-destructive/5")}>{action.icon || <MoreHorizontal className="size-4" />}</span>
                  <span className="min-w-0 flex-1"><span className="block font-medium">{action.label}</span>{action.description && <span className="block truncate text-xs text-muted-foreground">{action.description}</span>}</span>
                </CommandItem>)}
              </CommandGroup>
            </div>)}
          </CommandList>
        </Command>
      </DialogContent>
    </Dialog>
  </>
}

export function PageHeader({
  eyebrow,
  title,
  description,
  action,
}: {
  eyebrow: string
  title: string
  description: string
  action?: React.ReactNode
}) {
  return (
    <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-end sm:justify-between">
      <div className="min-w-0">
        <DetailBreadcrumb items={[{ label: "DataPlus", href: "/" }, { label: eyebrow }]} />
        <p className="text-xs font-bold uppercase tracking-wide text-muted-foreground">{eyebrow}</p>
        <h2 className="text-2xl font-semibold tracking-tight">{title}</h2>
        <p className="max-w-3xl text-sm text-muted-foreground">{description}</p>
      </div>
      {action && <div className="w-full sm:w-auto">{action}</div>}
    </div>
  )
}

export function Detail({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-md border bg-background p-2">
      <p className="text-xs font-bold uppercase tracking-wide text-muted-foreground">{label}</p>
      <p className="break-words font-medium">{value}</p>
    </div>
  )
}

export function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="grid gap-1.5">
      <Label className="text-xs font-bold text-muted-foreground">{label}</Label>
      {children}
    </div>
  )
}

export function ToggleField({
  label,
  description,
  checked,
  disabled,
  onCheckedChange,
}: {
  label: string
  description?: string
  checked: boolean
  disabled?: boolean
  onCheckedChange: (value: boolean) => void
}) {
  return (
    <div className="flex items-center justify-between gap-4 rounded-md border bg-background p-3">
      <div className="min-w-0">
        <Label className="text-sm font-medium">{label}</Label>
        {description && <p className="mt-1 text-xs leading-5 text-muted-foreground">{description}</p>}
      </div>
      <Switch checked={checked} disabled={disabled} onCheckedChange={onCheckedChange} />
    </div>
  )
}

function DataPlusApp() {
  // A separate mount prevents legacy state and job polling in a company workspace.
  if (['/orders/tools', '/orders/imports'].includes(window.location.pathname.replace(/\/+$/, ''))) return <App orderTools />
  if (window.location.pathname === '/organization') { window.location.replace('/settings?tab=companies'); return null }
  if (window.location.pathname.replace(/\/+$/, '') === '/settings' && new URLSearchParams(window.location.search).get('tab') === 'companies') return <App companySettings />
  return <App />
}

export default DataPlusApp

export async function launchWalmartExisting(selection: { skus: string[]; allFiltered?: boolean; query?: string; filters?: Record<string, string> }) {
  try {
    const response = await fetch('/api/walmart/launch/existing', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(selection) })
    const result = await response.json()
    if (!response.ok) throw new Error(result.error || 'Unable to launch on Walmart')
    toast.success(`Walmart launch queued: job ${result.job.jobNumber || result.job.id}. Eligible matches submit automatically in feeds of up to 1,000. Progress and automatic rate-limit waits appear in Jobs.`)
  } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to launch on Walmart') }
}
